using System.Text;

public static class CommandReader
{
    public static async Task<string> ReadCommandAsync(Stream stream)
    {
        var buffer = new byte[256];
        int read = await stream.ReadAsync(buffer);
        Memory<byte> line = buffer.AsMemory(0, read); // a view that can wait
        await Audit.LogAsync(read);
        return CommandName(line.Span); // back to a Span for synchronous work
    }

    private static string CommandName(ReadOnlySpan<byte> line)
    {
        int space = line.IndexOf((byte)' ');
        return Encoding.ASCII.GetString(space < 0 ? line : line[..space]);
    }
}

