public ref struct FieldReader(ReadOnlySpan<char> line)
{
    private ReadOnlySpan<char> _rest = line; // allowed: FieldReader is a ref struct

    public bool TryRead(out ReadOnlySpan<char> field)
    {
        if (_rest.IsEmpty) { field = default; return false; }
        int comma = _rest.IndexOf(',');
        field = comma < 0 ? _rest : _rest[..comma];
        _rest = comma < 0 ? default : _rest[(comma + 1)..];
        return true;
    }
}
